// PostServiceServer is the server API for PostService service.
// All implementations must embed UnimplementedPostServiceServer
// for forward compatibility.
type PostServiceServer interface {
	// Require an access token; the author is the caller. A post is deleted
	// by its author or by the owner of its wall; on a community's wall by
	// its admins too, whom post asks the club service about.
	CreatePost(context.Context, *CreatePostRequest) (*CreatePostResponse, error)
	DeletePost(context.Context, *DeletePostRequest) (*emptypb.Empty, error)
	// Requires an access token: shares a post on the caller's own wall. A
	// repost without text of a repost without text shares its original.
	RepostPost(context.Context, *RepostPostRequest) (*RepostPostResponse, error)
	// Requires an access token: the author changes the text and photos of
	// their post within a week of posting (editable_until); a repost keeps
	// what it shares and takes no photos.
	EditPost(context.Context, *EditPostRequest) (*EditPostResponse, error)
	// Require an access token: the owner of the wall (the admins of a
	// community) shows the post first on it, instead of the one pinned
	// before, or stops. Both idempotent.
	PinPost(context.Context, *PinPostRequest) (*emptypb.Empty, error)
	UnpinPost(context.Context, *UnpinPostRequest) (*emptypb.Empty, error)
	// Require an access token; the owner of the wall, or the admins of the
	// community it is. An archived post ("Архив записей" of openvk) is shown
	// to them only: no wall, feed or other post shows it, and it is no
	// longer pinned. A post with closed comments takes no new ones
	// (FailedPrecondition); those written before stay.
	ArchivePost(context.Context, *ArchivePostRequest) (*emptypb.Empty, error)
	UnarchivePost(context.Context, *UnarchivePostRequest) (*emptypb.Empty, error)
	// Requires an access token: puts away every post of a wall written in a
	// year, or puts them back ("Архивировать все записи за 2025" and
	// "Разархивировать все записи за 2025" of openvk); every year without
	// one ("Архивировать все записи целиком"). The owner of the wall or the
	// admins of its community only (PermissionDenied).
	ArchiveWall(context.Context, *ArchiveWallRequest) (*ArchiveWallResponse, error)
	// Requires an access token: the years the posts of a wall were written
	// in, archived or not, the latest first — the years of openvk's
	// archive. For those who keep the archive only (PermissionDenied).
	ListWallYears(context.Context, *ListWallYearsRequest) (*ListWallYearsResponse, error)
	CloseComments(context.Context, *CloseCommentsRequest) (*emptypb.Empty, error)
	OpenComments(context.Context, *OpenCommentsRequest) (*emptypb.Empty, error)
	// Public: one post.
	GetPost(context.Context, *GetPostRequest) (*GetPostResponse, error)
	// Public: at most 50 posts by ID, for the notifications page; posts that
	// are gone are left out, the order is not kept.
	GetPosts(context.Context, *GetPostsRequest) (*GetPostsResponse, error)
	// Public: how many posts there are on all walls, for the page "о сайте".
	CountPosts(context.Context, *CountPostsRequest) (*CountPostsResponse, error)
	// Public: a user's wall, newest first, whoever wrote the posts.
	ListPosts(context.Context, *ListPostsRequest) (*ListPostsResponse, error)
	// Public: the posts written by several authors on any walls, but for
	// those that speak for a community, and every post on several walls,
	// newest first, for a news feed.
	ListFeed(context.Context, *ListFeedRequest) (*ListFeedResponse, error)
	// Require an access token; the caller likes the post. Both are
	// idempotent and return how many likes the post has now.
	LikePost(context.Context, *LikePostRequest) (*LikePostResponse, error)
	UnlikePost(context.Context, *UnlikePostRequest) (*UnlikePostResponse, error)
	// Public: who like the post or the comment, newest first ("Понравилось
	// N людям" of openvk); total is its like counter.
	ListPostLikers(context.Context, *ListPostLikersRequest) (*ListPostLikersResponse, error)
	// Public: the posts that share a post (who shared it), newest first,
	// without the archived ones; NotFound for a missing or an archived post.
	ListReposts(context.Context, *ListRepostsRequest) (*ListRepostsResponse, error)
	ListCommentLikers(context.Context, *ListCommentLikersRequest) (*ListCommentLikersResponse, error)
	// openvk's "Закладки": what the caller likes, newest like first, for
	// them alone — posts, comments under posts and photos of albums. What
	// sits on an archived post is left out and not counted.
	ListLikedPosts(context.Context, *ListLikedPostsRequest) (*ListLikedPostsResponse, error)
	ListLikedComments(context.Context, *ListLikedCommentsRequest) (*ListLikedCommentsResponse, error)
	ListLikedAlbumPhotos(context.Context, *ListLikedAlbumPhotosRequest) (*ListLikedAlbumPhotosResponse, error)
	// What the caller wrote, on their wall and on others', newest first
	// ("Написанные мной записи" of openvk): not what was archived on the
	// wall of another, nor what they suggested for a community.
	ListOwnPosts(context.Context, *ListOwnPostsRequest) (*ListOwnPostsResponse, error)
	// The posts of every wall a query finds, newest first ("Поиск
	// записей" of openvk): one tag ("#поход") finds the posts that say it,
	// any other text the posts that say it as a part of theirs, in any
	// case. What "Все новости" (ListFeed with everyone) shows the caller,
	// and nothing for an empty query.
	SearchPosts(context.Context, *SearchPostsRequest) (*SearchPostsResponse, error)
	// Public: the polls of the posts that ask one ("Опрос" of openvk), at
	// most 100 posts, in no particular order; with an access token each
	// says what the caller chose. The poll of an archived post is given to
	// those who keep the archive only.
	GetPolls(context.Context, *GetPollsRequest) (*GetPollsResponse, error)
	// Require an access token: the caller's vote in the poll of a post,
	// cast once and changed by taking it back first. NotFound for a post
	// without a poll or archived away from the caller; FailedPrecondition
	// when the poll has ended, the caller has voted already (VotePoll), has
	// not, or the poll does not let a vote be taken back (RetractPollVote).
	VotePoll(context.Context, *VotePollRequest) (*VotePollResponse, error)
	RetractPollVote(context.Context, *RetractPollVoteRequest) (*RetractPollVoteResponse, error)
	// Public: who chose an option of a poll, newest first ("Список
	// проголосовавших" of openvk); FailedPrecondition for an anonymous poll.
	ListPollVoters(context.Context, *ListPollVotersRequest) (*ListPollVotersResponse, error)
	// Require an access token; the author is the caller. A comment is
	// deleted by its author, by the author of the post or by the owner of
	// the wall, the admins of a community.
	CreateComment(context.Context, *CreateCommentRequest) (*CreateCommentResponse, error)
	DeleteComment(context.Context, *DeleteCommentRequest) (*emptypb.Empty, error)
	// Require an access token; the caller likes the comment. Both are
	// idempotent and return how many likes the comment has now.
	LikeComment(context.Context, *LikeCommentRequest) (*LikeCommentResponse, error)
	UnlikeComment(context.Context, *UnlikeCommentRequest) (*UnlikeCommentResponse, error)
	// Public: the comments of a post, oldest first.
	ListComments(context.Context, *ListCommentsRequest) (*ListCommentsResponse, error)
	// Public: at most 50 comments by ID, like GetPosts.
	GetComments(context.Context, *GetCommentsRequest) (*GetCommentsResponse, error)
	// Public: the three newest comments of each of at most 50 posts, oldest
	// first, as "Микроблог" shows them under the posts of a wall. Archived
	// posts tell none.
	ListLastComments(context.Context, *ListLastCommentsRequest) (*ListLastCommentsResponse, error)
	// Require an access token: posts suggested for a community's wall
	// ("Предложка" of openvk), seen only by their authors and the
	// community's admins, whom post asks the club service about. The caller
	// of SuggestPost has checked that the author may suggest there and that
	// the photos are theirs.
	SuggestPost(context.Context, *SuggestPostRequest) (*SuggestPostResponse, error)
	// The caller's own suggestions with mine; all of them for the admins.
	ListSuggestions(context.Context, *ListSuggestionsRequest) (*ListSuggestionsResponse, error)
	// One suggestion, whole: for its author and the admins.
	GetSuggestion(context.Context, *GetSuggestionRequest) (*GetSuggestionResponse, error)
	// An admin publishes a suggestion as a new post for the community.
	PublishSuggestion(context.Context, *PublishSuggestionRequest) (*PublishSuggestionResponse, error)
	// The author withdraws a suggestion, or an admin declines it.
	DeleteSuggestion(context.Context, *DeleteSuggestionRequest) (*emptypb.Empty, error)
	// Require an access token: posts that wait for their time ("отложенные
	// записи" of VK), seen only by their authors and, on a community's
	// wall, the community's admins, whom post asks the club service about.
	// A post waits for the caller's own wall or speaks for a community: the
	// caller of PostponePost has checked that the author may and that the
	// photos are theirs. When its time comes, post publishes it as a new
	// post, dated then.
	PostponePost(context.Context, *PostponePostRequest) (*PostponePostResponse, error)
	// All the posts that wait for a wall, the soonest first: for the owner
	// of a user's wall and the admins of a community.
	ListPostponed(context.Context, *ListPostponedRequest) (*ListPostponedResponse, error)
	// One postponed post, whole: for those who list it and its author.
	GetPostponed(context.Context, *GetPostponedRequest) (*GetPostponedResponse, error)
	// The author, or an admin of the community it speaks for, changes what
	// it says and when it comes out.
	EditPostponed(context.Context, *EditPostponedRequest) (*EditPostponedResponse, error)
	// The same publish it at once ("Опубликовать сейчас").
	PublishPostponed(context.Context, *PublishPostponedRequest) (*PublishPostponedResponse, error)
	// The author takes it back, or an admin deletes it, with its photos.
	DeletePostponed(context.Context, *DeletePostponedRequest) (*emptypb.Empty, error)
	// Require an access token: stories ("истории" of VK; openvk has none),
	// a photo with a few words a person shows for a day to those who read
	// them. The caller of CreateStory has checked with the media service
	// that the photo is theirs; post keeps it for good at once and deletes
	// it with the story when the day is over.
	CreateStory(context.Context, *CreateStoryRequest) (*CreateStoryResponse, error)
	// The stories above the caller's news: theirs and of the people they
	// follow, grouped by author — the caller first, then those with a story
	// the caller has not viewed, then the rest; each one's stories the
	// oldest first. A deleted page and a closed one keep theirs to
	// themselves, as their walls.
	ListFeedStories(context.Context, *ListFeedStoriesRequest) (*ListFeedStoriesResponse, error)
	// The live stories of one person the caller sees, the oldest first.
	ListUserStories(context.Context, *ListUserStoriesRequest) (*ListUserStoriesResponse, error)
	// A live story the caller sees.
	GetStory(context.Context, *GetStoryRequest) (*GetStoryResponse, error)
	// The caller viewed a story they see; once is enough. Their own is not
	// counted.
	ViewStory(context.Context, *ViewStoryRequest) (*emptypb.Empty, error)
	// Who viewed a story, the latest first: for its author alone.
	ListStoryViewers(context.Context, *ListStoryViewersRequest) (*ListStoryViewersResponse, error)
	// The author deletes a story with its photo.
	DeleteStory(context.Context, *DeleteStoryRequest) (*emptypb.Empty, error)
	// The caller likes a story they see, or takes the like back; both are
	// idempotent. Its author hears of the like.
	LikeStory(context.Context, *LikeStoryRequest) (*emptypb.Empty, error)
	UnlikeStory(context.Context, *UnlikeStoryRequest) (*emptypb.Empty, error)
	// The caller comments a story they see, in text only; its author hears
	// of it. The caller of CreateStoryComment has checked the blacklist.
	CreateStoryComment(context.Context, *CreateStoryCommentRequest) (*CreateStoryCommentResponse, error)
	// The comments of a story the caller sees, the oldest first.
	ListStoryComments(context.Context, *ListStoryCommentsRequest) (*ListStoryCommentsResponse, error)
	// The author of a comment or of its story deletes it.
	DeleteStoryComment(context.Context, *DeleteStoryCommentRequest) (*emptypb.Empty, error)
	// The discussions of communities ("Обсуждения" of openvk). The caller
	// of CreateTopic has checked with the club service that the author may
	// start a topic there and, with from_wall, speak for the community, and
	// that the photos are theirs; the rest post asks the club service about.
	CreateTopic(context.Context, *CreateTopicRequest) (*CreateTopicResponse, error)
	// Public.
	GetTopic(context.Context, *GetTopicRequest) (*GetTopicResponse, error)
	// Public: the topics of a club, pinned first, then the most recently
	// active.
	ListTopics(context.Context, *ListTopicsRequest) (*ListTopicsResponse, error)
	// The author or an admin renames and closes a topic; only an admin pins
	// and restricts it.
	EditTopic(context.Context, *EditTopicRequest) (*EditTopicResponse, error)
	DeleteTopic(context.Context, *DeleteTopicRequest) (*emptypb.Empty, error)
	// Nobody writes in a closed topic, only the admins in a restricted one.
	// The caller has checked from_wall and the photos, as for CreateTopic.
	CreateTopicMessage(context.Context, *CreateTopicMessageRequest) (*CreateTopicMessageResponse, error)
	// Public: oldest first.
	ListTopicMessages(context.Context, *ListTopicMessagesRequest) (*ListTopicMessagesResponse, error)
	// Public: one message, whole; liked is not told.
	GetTopicMessage(context.Context, *GetTopicMessageRequest) (*GetTopicMessageResponse, error)
	// Its author or an admin.
	DeleteTopicMessage(context.Context, *DeleteTopicMessageRequest) (*emptypb.Empty, error)
	// A heart on a message of a topic, as on a comment; idempotent, nobody
	// is notified.
	LikeTopicMessage(context.Context, *LikeTopicMessageRequest) (*LikeTopicMessageResponse, error)
	UnlikeTopicMessage(context.Context, *UnlikeTopicMessageRequest) (*UnlikeTopicMessageResponse, error)
	// Who put a heart on a message of a topic, newest first ("Понравилось N
	// людям"). Public.
	ListTopicMessageLikers(context.Context, *ListTopicMessageLikersRequest) (*ListTopicMessageLikersResponse, error)
	// The messages of topics with these IDs that exist, in no order: a
	// notification quotes them. Public.
	GetTopicMessages(context.Context, *GetTopicMessagesRequest) (*GetTopicMessagesResponse, error)
	// Photo albums of people and communities ("Альбомы" of openvk). An
	// album of the caller, without club_id, or of a community its admins
	// create, whom post asks the club service about.
	CreateAlbum(context.Context, *CreateAlbumRequest) (*CreateAlbumResponse, error)
	// Public.
	GetAlbum(context.Context, *GetAlbumRequest) (*GetAlbumResponse, error)
	// Public: the albums of a person or a community, newest first.
	ListAlbums(context.Context, *ListAlbumsRequest) (*ListAlbumsResponse, error)
	// Its owner or the admins of the community that owns it.
	EditAlbum(context.Context, *EditAlbumRequest) (*EditAlbumResponse, error)
	// With its photos; as EditAlbum.
	DeleteAlbum(context.Context, *DeleteAlbumRequest) (*emptypb.Empty, error)
	// Up to 10 photos the caller uploaded, which the caller of
	// AddAlbumPhotos has checked with the media service; as EditAlbum.
	AddAlbumPhotos(context.Context, *AddAlbumPhotosRequest) (*AddAlbumPhotosResponse, error)
	// A new photo of a page, which the caller uploaded and the caller of
	// AddAvatarPhoto has checked with the media service, goes into its
	// "Фотографии со страницы", made with the first one: the caller's page
	// or of a community they run.
	AddAvatarPhoto(context.Context, *AddAvatarPhotoRequest) (*AddAvatarPhotoResponse, error)
	// Public: oldest first.
	ListAlbumPhotos(context.Context, *ListAlbumPhotosRequest) (*ListAlbumPhotosResponse, error)
	// Public: a photo with its album.
	GetAlbumPhoto(context.Context, *GetAlbumPhotoRequest) (*GetAlbumPhotoResponse, error)
	// Who uploaded the photo only.
	EditAlbumPhoto(context.Context, *EditAlbumPhotoRequest) (*EditAlbumPhotoResponse, error)
	// Who uploaded it or whoever may edit its album.
	DeleteAlbumPhoto(context.Context, *DeleteAlbumPhotoRequest) (*emptypb.Empty, error)
	// Require an access token; whoever may edit the album. SetAlbumCover
	// makes a photo of the album show it ("Обложка альбома") instead of its
	// first one. MoveAlbumPhoto puts a photo in another album of the same
	// owner, one made by people (FailedPrecondition for one the site keeps).
	SetAlbumCover(context.Context, *SetAlbumCoverRequest) (*emptypb.Empty, error)
	MoveAlbumPhoto(context.Context, *MoveAlbumPhotoRequest) (*emptypb.Empty, error)
	// Require an access token: the heart under a photo, as under a post.
	LikeAlbumPhoto(context.Context, *LikeAlbumPhotoRequest) (*LikeAlbumPhotoResponse, error)
	UnlikeAlbumPhoto(context.Context, *UnlikeAlbumPhotoRequest) (*UnlikeAlbumPhotoResponse, error)
	// Public: who like the photo, newest first, as ListPostLikers.
	ListAlbumPhotoLikers(context.Context, *ListAlbumPhotoLikersRequest) (*ListAlbumPhotoLikersResponse, error)
	// Requires an access token: a comment under a photo, text only; the
	// caller of CreatePhotoComment has checked the blacklists.
	CreatePhotoComment(context.Context, *CreatePhotoCommentRequest) (*CreatePhotoCommentResponse, error)
	// Requires an access token: its author, who uploaded the photo, the
	// owner of the album or the admins of its community.
	DeletePhotoComment(context.Context, *DeletePhotoCommentRequest) (*emptypb.Empty, error)
	// Public: the comments of a photo, oldest first.
	ListPhotoComments(context.Context, *ListPhotoCommentsRequest) (*ListPhotoCommentsResponse, error)
	// Public: one comment, whole.
	GetPhotoComment(context.Context, *GetPhotoCommentRequest) (*GetPhotoCommentResponse, error)
	// The comments of photos with these IDs that exist, in no order: a
	// notification quotes them. Public.
	GetPhotoComments(context.Context, *GetPhotoCommentsRequest) (*GetPhotoCommentsResponse, error)
	// A heart on a comment of a photo, as on a comment of a post:
	// idempotent, the response counts them.
	LikePhotoComment(context.Context, *LikePhotoCommentRequest) (*LikePhotoCommentResponse, error)
	UnlikePhotoComment(context.Context, *UnlikePhotoCommentRequest) (*UnlikePhotoCommentResponse, error)
	// Who put a heart on a comment of a photo, newest first. Public.
	ListPhotoCommentLikers(context.Context, *ListPhotoCommentLikersRequest) (*ListPhotoCommentLikersResponse, error)
	// Notes ("Заметки" of openvk): a person's titled texts, kept apart from
	// the wall. Reading is public: who sees the notes of a person is the
	// person's (the user service), which the caller asks. Only the author
	// changes and deletes a note; a deleted note takes its comments.
	CreateNote(context.Context, *CreateNoteRequest) (*CreateNoteResponse, error)
	GetNote(context.Context, *GetNoteRequest) (*GetNoteResponse, error)
	// Public: the notes of a person, newest first.
	ListNotes(context.Context, *ListNotesRequest) (*ListNotesResponse, error)
	EditNote(context.Context, *EditNoteRequest) (*EditNoteResponse, error)
	DeleteNote(context.Context, *DeleteNoteRequest) (*emptypb.Empty, error)
	// A comment under a note, text only; the author of the note hears
	// about it. The caller has checked who may comment.
	CreateNoteComment(context.Context, *CreateNoteCommentRequest) (*CreateNoteCommentResponse, error)
	// By its author or the author of the note.
	DeleteNoteComment(context.Context, *DeleteNoteCommentRequest) (*emptypb.Empty, error)
	// Public: the comments of a note, oldest first.
	ListNoteComments(context.Context, *ListNoteCommentsRequest) (*ListNoteCommentsResponse, error)
	// Public: one comment, whole.
	GetNoteComment(context.Context, *GetNoteCommentRequest) (*GetNoteCommentResponse, error)
	// Public: the comments with these IDs that exist, in no particular
	// order, for notifications.
	GetNoteComments(context.Context, *GetNoteCommentsRequest) (*GetNoteCommentsResponse, error)
	// Documents ("Мои Документы" of openvk): files of a person whose bytes
	// the media service keeps under the same ID; posts and messages attach
	// them. Only the owner lists, renames and deletes them.
	AddDocument(context.Context, *AddDocumentRequest) (*AddDocumentResponse, error)
	// The caller's documents, newest first.
	ListDocuments(context.Context, *ListDocumentsRequest) (*ListDocumentsResponse, error)
	// Public: the documents with these IDs that exist, in no particular
	// order, for what attaches them.
	GetDocuments(context.Context, *GetDocumentsRequest) (*GetDocumentsResponse, error)
	RenameDocument(context.Context, *RenameDocumentRequest) (*RenameDocumentResponse, error)
	// The media service deletes the bytes after; what attached the
	// document loses it.
	DeleteDocument(context.Context, *DeleteDocumentRequest) (*emptypb.Empty, error)
	// Internal, for user: the user's page was deleted and not restored in
	// time. Their posts and the posts on their wall go, with all their likes
	// and comments, and their likes and comments on others' posts. Idempotent.
	PurgeUser(context.Context, *PurgeUserRequest) (*emptypb.Empty, error)
	// Internal, for club: the community is gone. The posts on its wall go,
	// with their likes and comments, and so do what was suggested and
	// postponed for it, its topics and its albums. Idempotent.
	PurgeClub(context.Context, *PurgeClubRequest) (*emptypb.Empty, error)
	// Internal, for user: the user deleted their page. Their likes and
	// their votes in polls leave the counts and the lists of who liked,
	// kept aside until the page is restored or erased. Idempotent.
	HoldUserReactions(context.Context, *HoldUserReactionsRequest) (*emptypb.Empty, error)
	// Internal, for user: the user restored their page. What was kept
	// aside is counted again, but for what was deleted meanwhile.
	// Idempotent.
	ReleaseUserReactions(context.Context, *ReleaseUserReactionsRequest) (*emptypb.Empty, error)
	// Internal, for user and club: the reader follows a person or joined a
	// community, whose posts are in the reader's news (ListFeed) from now
	// on. Idempotent.
	FollowSource(context.Context, *FollowSourceRequest) (*emptypb.Empty, error)
	// Internal, for user and club: the reader no longer follows the person
	// or left the community. Idempotent.
	UnfollowSource(context.Context, *UnfollowSourceRequest) (*emptypb.Empty, error)
	// Internal, for user and club: a stretch of whom the reader follows, or
	// of who is in the community, as the service has it now. What the news
	// keep within the stretch becomes exactly that: told now and then, it
	// mends whatever a lost FollowSource or UnfollowSource left behind.
	// Idempotent.
	SyncSources(context.Context, *SyncSourcesRequest) (*emptypb.Empty, error)
	// Internal, for user and club: the wall is closed — of a person whose
	// profile is closed, read by the owner and those the owner follows, or
	// of a closed community, read by its members. The others do not find
	// its posts, in the news or by ID. Idempotent.
	CloseWall(context.Context, *CloseWallRequest) (*emptypb.Empty, error)
	// Internal, for user and club: everyone reads the wall again.
	// Idempotent.
	OpenWall(context.Context, *OpenWallRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedPostServiceServer()
}

